// sel-fill-noair v1
// Parche: Shift+número con herramienta Seleccionar y caja confirmada
// rellena SOLO los bloques sólidos (no aire) de la selección.
// Sin Shift el comportamiento no cambia (rellena todo, aire incluido).
//
// API:
//   game.selFillNoAir.on()      activa
//   game.selFillNoAir.off()     restaura
//   game.selFillNoAir.estado()  info
//
(() => {
'use strict';

let activo = false;
let stats = { ops: 0 };
let handler = null;

// Versión de mcSelectFillId que recorre SOLO los sólidos (mcSelForEach en
// vez de mcSelForEachConAire) — idéntica salvo por el iterador.
function fillSoloSolidos(id, yaHecha){
  if(mc.tool !== 'select' || !mc.selBox || !id) return false;
  const celdas = [];
  // mcSelForEach salta las celdas con id===0 (aire)
  mcSelForEach((x, y, z, before) => celdas.push([x, y, z, before]));
  if(!celdas.length){ toast('Nada que reemplazar (no hay sólidos)'); return true; }
  const edits = [];
  let desde = 0;
  if(yaHecha){ edits.push(yaHecha); desde = 1; }
  for(let n = desde; n < celdas.length; n++){
    const [x, y, z, before] = celdas[n];
    if(before === id) continue;
    mc.grid[mcIdx(x, y, z)] = id;
    mcDirty(x, y, z);
    mcGlowTocada(x, y, z);
    edits.push({x, y, z, before, after: id});
  }
  if(!edits.length){ toast('Nada que reemplazar'); return true; }
  mcRemeshEdiciones(edits);
  mcPushHist({t: 'bb', edits});
  mcScheduleSave();
  toast(edits.length + ' sólido(s) reemplazados con ' + mcNombreMat(mc.blockKey[id] || ''));
  stats.ops++;
  return true;
}

// Relleno solo-sólidos con la pieza de la ranura (mismo camino que
// mcSelectFillPieza pero desemboca en fillSoloSolidos).
function fillPiezaSolidos(sk, quien){
  if(mc.tool !== 'select' || !mc.selBox) return false;
  let vk = sk;
  if(mc.structs[sk] || (mc.slotStruct && mc.slotStruct.indexOf(sk) >= 0)){
    if(!mcCabeEnRejilla(sk)){ toast('«' + sk + '» ocupa más de un bloque: no sirve para reemplazar'); return false; }
    const oriPed = mcPreviewOri(), ori = mcEsFinaEnRejilla(sk) ? oriPed : 0;
    if(oriPed && !ori) toast('«' + sk + '» se proyecta sobre el cubo: en la rejilla no puede enseñar el giro');
    vk = mcClaveConOri(sk, ori);
  }
  let p = null;
  mcSelForEach((x, y, z, before) => { if(!p) p = [x, y, z, before]; });
  if(!p){ toast('Nada que reemplazar (no hay sólidos)'); return true; }
  const lock = mc.histLock;
  let puesto;
  mc.histLock = true;
  try{ puesto = mcPonEnRejilla(p[0], p[1], p[2], vk); } finally { mc.histLock = lock; }
  if(puesto === false){ toast('Ahí no cabe la pieza'); return false; }
  const id = mc.grid[mcIdx(p[0], p[1], p[2])];
  if(!id || id === p[3]){
    if(mc.blockKey[p[3]] === vk) return fillSoloSolidos(p[3]);
    toast(quien + ' aún se está cargando — vuelve a pulsar'); return false;
  }
  return fillSoloSolidos(id, {x: p[0], y: p[1], z: p[2], before: p[3], after: id});
}

// Entrada: igual que mcSelectFill pero llama a fillSoloSolidos.
function selectFillNoAir(i){
  if(mc.tool !== 'select' || !mc.selBox) return false;
  const sk = mc.slotStruct && mc.slotStruct[i];
  if(sk) return fillPiezaSolidos(sk, 'La pieza de la ranura ' + (i + 1));
  return fillSoloSolidos(mc.hotbar[i]);
}

function onKey(e){
  if(!mc.active || !mc.selBox || mc.tool !== 'select') return;
  if(!e.shiftKey) return;
  // Shift+número en teclado español: e.key NO es el dígito, pero e.code sí.
  const m = /^Digit([1-9])$/.exec(e.code);
  if(!m) return;
  const i = +m[1] - 1;
  if(i >= mc.hotbar.length) return;
  // Activar la ranura (como hace el número sin Shift)
  mc.sel = i; mcSelectSlot();
  // Rellenar solo sólidos
  selectFillNoAir(i);
  e.preventDefault();
  e.stopImmediatePropagation();
}

function instalar(){
  handler = onKey;
  window.addEventListener('keydown', handler, true);  // capture: antes que el handler del Mundo
  activo = true;
}

function desinstalar(){
  if(handler) window.removeEventListener('keydown', handler, true);
  handler = null;
  activo = false;
}

function estado(){
  const s = 'sel-fill-noair: ' + (activo ? 'ACTIVO' : 'inactivo') + ' · ops: ' + stats.ops;
  console.log(s);
  return s;
}

const API = {
  on(){ if(!activo) instalar(); return 'sel-fill-noair activado'; },
  off(){ if(activo) desinstalar(); return 'sel-fill-noair desactivado'; },
  estado
};
game.selFillNoAir = API;
API.on();
})();
